import type { DataPlot, DataTable, Difficulty, DomainId } from '../../types'

interface Blueprint {
  id: string
  skillId: string
  domain: DomainId
  difficulty: Difficulty
  stimulus?: string
  secondaryStimulus?: string
  table?: DataTable
  plot?: DataPlot
  prompt: string
  choices: string[]
  answer: number
  explanation: string
  traps: string[]
}

const domainBySkill: Record<string, DomainId> = {
  'words-in-context': 'craft-structure',
  'text-structure-purpose': 'craft-structure',
  'cross-text-connections': 'craft-structure',
  'central-ideas-details': 'information-ideas',
  'command-evidence-textual': 'information-ideas',
  'command-evidence-quantitative': 'information-ideas',
  inferences: 'information-ideas',
  boundaries: 'standard-english',
  'form-structure-sense': 'standard-english',
  'rhetorical-synthesis': 'expression-ideas',
  transitions: 'expression-ideas',
}

const make = (
  number: number,
  skillId: string,
  difficulty: Difficulty,
  stimulus: string,
  promptOrChoices: string | string[],
  choicesOrAnswer: string[] | number,
  answerOrExplanation: number | string,
  explanationOrTraps: string | string[],
  trapsOrExtra: string[] | Partial<Pick<Blueprint, 'secondaryStimulus' | 'table' | 'plot'>> = {},
  extraMaybe: Partial<Pick<Blueprint, 'secondaryStimulus' | 'table' | 'plot'>> = {},
): Blueprint => {
  const hasPrompt = typeof promptOrChoices === 'string'
  const prompt = hasPrompt
    ? promptOrChoices
    : skillId === 'transitions'
      ? 'Which choice completes the text with the most logical transition?'
      : 'Which choice completes the text so that it conforms to the conventions of Standard English?'
  const choices = (hasPrompt ? choicesOrAnswer : promptOrChoices) as string[]
  const answer = (hasPrompt ? answerOrExplanation : choicesOrAnswer) as number
  const explanation = (hasPrompt ? explanationOrTraps : answerOrExplanation) as string
  const traps = (hasPrompt ? trapsOrExtra : explanationOrTraps) as string[]
  const extra = (hasPrompt ? extraMaybe : {})
  const pairedMatch = stimulus.match(/^Text 1:\s*([\s\S]*?)\n\nText 2:\s*([\s\S]*)$/)
  const wrongTraps = traps.filter((trap) => trap !== 'Supported')
  const normalizedTraps = Array.from({ length: 4 }, (_, index) => (
    index === answer ? 'Supported' : wrongTraps.shift() ?? 'This choice is not supported by the text.'
  ))
  return {
    id: `agent-a-rw-${String(number).padStart(3, '0')}`,
    skillId,
    domain: domainBySkill[skillId],
    difficulty,
    stimulus: pairedMatch?.[1] ?? stimulus,
    prompt,
    choices,
    answer,
    explanation,
    traps: normalizedTraps,
    ...extra,
    ...(pairedMatch ? { secondaryStimulus: pairedMatch[2] } : {}),
  }
}

