export const newItems: Blueprint[] = allItems
  .filter((item) => {
    const numericId = Number(item.id.slice(-3))
    return !(item.skillId === 'command-evidence-textual' && numericId >= 117 && numericId <= 153)
  })
  .map((item, index) => {
    const targetAnswer = index % 4
    const remainingChoices = [0, 1, 2, 3].filter((choiceIndex) => choiceIndex !== item.answer)
    const order = Array.from({ length: 4 }, (_, position) => (
      position === targetAnswer ? item.answer : remainingChoices.shift() as number
    ))
    return {
      ...item,
      id: `agent-a-rw-${String(index + 1).padStart(3, '0')}`,
      choices: order.map((choiceIndex) => item.choices[choiceIndex]),
      answer: targetAnswer,
      traps: order.map((choiceIndex) => item.traps[choiceIndex]),
    }
  })
